#!/usr/bin/env bash
# Majorité, étape 1 — groupes système (avec MIGRATION 20261221000000_system_groups).
# - Instructeurs et Bureau deviennent des groupes SYSTÈME (un « Bureau » existant est adopté, avec ses membres),
#   sous Administrateurs, impossibles à supprimer ;
# - leurs membres (et ceux d'Administrateurs) sont majeurs d'office : un mineur y est refusé ;
# - Instructeurs = vivier des affectations ; au démarrage, les instructeurs déjà affectés y entrent ;
# - téléphone du parent référent (colonne, utilisée à l'étape 2) ; guide admin ; e2e groupes-systeme.
# Prérequis : apply-formulaires-compiler.sh.
# Usage (racine du repo) : bash apply-majorite-1-groupes-systeme.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"prisma/schema.prisma" 2>/dev/null | grep -qF "enum SystemGroupKind"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "use no memo" "apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" 2>/dev/null || { echo "lancez d'abord apply-formulaires-compiler.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/gerer-un-groupe.mdx" "apps/web/src/app/(admin)/dashboard/groups/[id]/page.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/instrumentation.ts" "e2e/data.mjs" "packages/backend/src/modules/memberGroups/deleteGroupWithSpace.service.ts" "packages/backend/src/modules/memberGroups/router.ts" "packages/backend/src/modules/users/router.ts" "prisma/schema.prisma")
CREATED=("e2e/groupes-systeme.spec.ts" "packages/backend/src/modules/memberGroups/systemGroups.service.ts" "packages/contracts/src/groups/systemGroups.ts" "prisma/migrations/20261221000000_system_groups/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261221000000_system_groups" 2>/dev/null || true; rmdir -p "packages/contracts/src/groups" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "enum SystemGroupKind" "prisma/schema.prisma" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

